import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/registry/ndeko/ui/accordion';

import { CATEGORIES } from './data';

const LINK =
  'text-foreground/80 hover:text-foreground focus-visible:ring-ring/25 rounded-sm text-[13px] transition-colors outline-none focus-visible:ring-[3px]';

export function Sitemap() {
  return (
    <nav aria-label='Footer'>
      <Accordion className='sm:hidden'>
        {CATEGORIES.map((category) => (
          <AccordionItem key={category.title} value={category.title}>
            <AccordionTrigger>{category.title}</AccordionTrigger>
            <AccordionContent>
              <ul className='flex flex-col gap-2.5 pb-1'>
                {category.links.map((link) => (
                  <li key={link.label}>
                    <a href={link.href} className={LINK}>
                      {link.label}
                    </a>
                  </li>
                ))}
              </ul>
            </AccordionContent>
          </AccordionItem>
        ))}
      </Accordion>
      <div className='hidden gap-x-6 gap-y-10 sm:grid sm:grid-cols-3 lg:grid-cols-5'>
        {CATEGORIES.map((category) => (
          <div key={category.title} className='flex flex-col gap-3'>
            <h2 className='text-muted-foreground text-xs font-medium'>
              {category.title}
            </h2>
            <ul className='flex flex-col gap-2'>
              {category.links.map((link) => (
                <li key={link.label}>
                  <a href={link.href} className={LINK}>
                    {link.label}
                  </a>
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>
    </nav>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useEffect, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { CheckIcon, CopyIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/registry/ndeko/ui/tooltip';

const COPIED_RESET_MS = 1600;

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const ICON_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function iconVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return ICON_VARIANTS;
}

function copyGlyphOf(isCopied: boolean) {
  if (isCopied) {
    return {
      key: 'copied',
      icon: <CheckIcon className='text-success-foreground' />,
    };
  }
  return { key: 'copy', icon: <CopyIcon /> };
}

function tooltipLabelOf(isCopied: boolean) {
  if (isCopied) {
    return 'Copied';
  }
  return 'Copy address';
}

export function CopyEmail({ email }: { email: string }) {
  const [isCopied, setIsCopied] = useState(false);
  const shouldReduceMotion = usePrefersReducedMotion();
  const iconVariants = iconVariantsOf(shouldReduceMotion);
  const glyph = copyGlyphOf(isCopied);

  useEffect(() => {
    if (!isCopied) {
      return;
    }
    const timeout = window.setTimeout(() => {
      setIsCopied(false);
    }, COPIED_RESET_MS);
    return () => window.clearTimeout(timeout);
  }, [isCopied]);

  async function copyEmail() {
    try {
      await navigator.clipboard.writeText(email);
      setIsCopied(true);
    } catch {
      setIsCopied(false);
    }
  }

  return (
    <div className='flex items-center gap-1'>
      <a
        href={`mailto:${email}`}
        className='text-primary-ink focus-visible:ring-ring/25 rounded-sm text-[13px] font-medium underline-offset-4 outline-none hover:underline focus-visible:ring-[3px]'
      >
        {email}
      </a>
      <Tooltip>
        <TooltipTrigger
          delay={0}
          render={
            <Button
              variant='ghost'
              size='icon-sm'
              className='text-muted-foreground'
              aria-label={`Copy ${email}`}
              onClick={copyEmail}
            />
          }
        >
          <AnimatePresence mode='popLayout' initial={false}>
            <motion.span
              key={glyph.key}
              className='flex'
              variants={iconVariants}
              initial='enter'
              animate='visible'
              exit='exit'
              transition={SWAP_TRANSITION}
            >
              {glyph.icon}
            </motion.span>
          </AnimatePresence>
        </TooltipTrigger>
        <TooltipContent>{tooltipLabelOf(isCopied)}</TooltipContent>
      </Tooltip>
      <span className='sr-only' role='status'>
        {isCopied && 'Email address copied'}
      </span>
    </div>
  );
}

'use client';

